/**
 * Calculate category-specific SP earning and spending caps.
 * 
 * TASK ADMIN-V3-007: Per-category SP configuration.
 * Uses category's `sp_earning_multiplier` and `sp_spending_cap_percent`.
 * Returns SP amounts that match the admin portal's calculation exactly.
 *
 * @param categoryId - Category ID
 * @param price - Item price in dollars
 * @returns {earn_sp, max_spend_sp, spend_percent} or defaults if category not found
 */
export async function calculateCategorySP(
  categoryId: string,
  price: number
): Promise<{ earn_sp: number; max_spend_sp: number; spend_percent: number }> {
  try {
    const { data: category, error } = await supabase
      .from('categories')
      .select('sp_earning_multiplier, sp_spending_cap_percent')
      .eq('id', categoryId)
      .single();

    if (error || !category) {
      // Default fallback: 1.10 multiplier, 50% cap
      return {
        earn_sp: Math.round(price * 1.10),
        max_spend_sp: Math.floor(price * 0.50),
        spend_percent: 50,
      };
    }

    const multiplier = category.sp_earning_multiplier ?? 1.10;
    const capPercent = category.sp_spending_cap_percent ?? 50;

    return {
      earn_sp: Math.round(price * multiplier),
      max_spend_sp: Math.floor(price * (capPercent / 100)),
      spend_percent: capPercent,
    };
  } catch (error: any) {
    console.error('[categoryService] Calculate category SP error:', error);
    // Safe fallback
    return {
      earn_sp: Math.round(price * 1.10),
      max_spend_sp: Math.floor(price * 0.50),
      spend_percent: 50,
    };
  }
}

/**
 * Get bonus categories (sp_earning_multiplier > 1.10).
 * Used by buyer flows to highlight high-earning categories.
 *
 * @returns Array of categories with bonus earning rates
 */
export async function getBonusCategories(): Promise<CategoryWithCount[]> {
  try {
    const { data: categories, error } = await supabase
      .from('categories')
      .select(`
        id,
        name,
        icon,
        is_active,
        display_order,
        sp_earning_multiplier,
        bonus_badge_icon_url
      `)
      .eq('is_active', true)
      .gt('sp_earning_multiplier', 1.10)
      .order('sp_earning_multiplier', { ascending: false });

    if (error) throw error;

    return categories || [];
  } catch (error: any) {
    console.error('[categoryService] Get bonus categories error:', error);
    return [];
  }
}

