 * 
 * Features:
 * - 4 price tier cards (great_deal, fair_price, asking_price, almost_new)
 * - Manual price input option
 * - Show manual-only when no suggestions available
 * - SP earning and spending caps based on category configuration
 */

import React, { useEffect, useState } from 'react';
import {
  View,
  Text,
  TouchableOpacity,
  TextInput,
  StyleSheet,
  ActivityIndicator,
} from 'react-native';
import { PriceTier, PriceSuggestion } from '../../types/listing';
import { calculateCategorySP } from '../../services/categoryService';

export interface PriceSuggestionCardProps {
  tiers: PriceSuggestion[];
  selectedTier: PriceTier | null;
  manualValue: string;
  onSelectTier: (tier: PriceTier) => void;
  onChangeManual: (value: string) => void;
  onShowFaq?: () => void;
  /**
   * TASK ADMIN-V3-007: Category ID for SP calculation
   */
  categoryId?: string | null;
  /**
   * TASK ADMIN-V3-007: Current price (from selected tier or manual input)
   */
  price?: number;
  testID?: string;
}

export function PriceSuggestionCard({
  tiers,
  selectedTier,
  manualValue,
  onSelectTier,
  onChangeManual,
  onShowFaq,
  categoryId,
  price,
  testID = 'price-suggestion-card',
}: PriceSuggestionCardProps) {
  const hasSuggestions = tiers.length > 0;

  // TASK ADMIN-V3-007: Calculate category-specific SP rates
  const [spInfo, setSPInfo] = useState<{ earn_sp: number; max_spend_sp: number; spend_percent: number } | null>(null);
  const [loadingSP, setLoadingSP] = useState(false);

  useEffect(() => {
    if (categoryId && price && price > 0) {
      setLoadingSP(true);
      calculateCategorySP(categoryId, price)
        .then((info) => setSPInfo(info))
        .catch((err) => {
          console.error('[PriceSuggestionCard] Failed to calculate SP:', err);
          setSPInfo(null);
        })
        .finally(() => setLoadingSP(false));
    } else {
      setSPInfo(null);
    }
  }, [categoryId, price]);

  return (
    <View style={styles.container} testID={testID}>
      <View style={styles.header}>
        <Text style={styles.title}>Price</Text>
        {onShowFaq && (
          <TouchableOpacity
            onPress={onShowFaq}
            accessibilityLabel="Show pricing FAQ"
            accessibilityRole="button"
            testID="pricing-faq"
          >
            <Text style={styles.faqButton}>?</Text>
          </TouchableOpacity>
        )}
      </View>

      {hasSuggestions ? (
        <>
          <Text style={styles.subtitle}>Suggested pricing based on similar items:</Text>

          <View style={styles.tiersContainer}>
            {tiers.map((tier) => {
              const isSelected = selectedTier === tier.tier;

              return (
                <TouchableOpacity
                  key={tier.tier}
                  style={[styles.tierCard, isSelected && styles.tierCardSelected]}
                  onPress={() => onSelectTier(tier.tier)}
                  accessibilityLabel={`${tier.label}: $${tier.price.toFixed(2)}`}
                  accessibilityHint={tier.description}
                  accessibilityRole="button"
                  accessibilityState={{ selected: isSelected }}
                  testID={`tier-${tier.tier}`}
                >
                  <Text style={[styles.tierLabel, isSelected && styles.tierLabelSelected]}>
                    {tier.label}
                  </Text>
                  <Text style={[styles.tierPrice, isSelected && styles.tierPriceSelected]}>
                    ${tier.price.toFixed(2)}
                  </Text>
                  <Text style={[styles.tierDescription, isSelected && styles.tierDescriptionSelected]}>
                    {tier.description}
                  </Text>
                </TouchableOpacity>
              );
            })}
          </View>

          <View style={styles.divider}>
            <View style={styles.dividerLine} />
            <Text style={styles.dividerText}>OR</Text>
            <View style={styles.dividerLine} />
          </View>
        </>
      ) : (
        <Text style={styles.noSuggestionsText}>
          Not enough data to suggest pricing. Set your price below.
        </Text>
      )}

      <View style={styles.manualInputContainer}>
        <Text style={styles.manualLabel}>Set custom price</Text>
        <View style={styles.inputWrapper}>
          <Text style={styles.currencySymbol}>$</Text>
          <TextInput
            style={styles.input}
            value={manualValue}
            onChangeText={onChangeManual}
            placeholder="0.00"
            keyboardType="decimal-pad"
            maxLength={10}
            accessibilityLabel="Manual price input"
            testID="manual-price-input"
          />
        </View>
      </View>

      {/* TASK ADMIN-V3-007: Display SP earning and spending info */}
      {categoryId && price && price > 0 && (
        <View style={styles.spInfoContainer} testID="sp-info">
          {loadingSP ? (
            <ActivityIndicator size="small" color="#3b82f6" />
          ) : spInfo ? (
            <>
              <View style={styles.spRow}>
                <Text style={styles.spLabel}>🌟 Seller earns:</Text>
                <Text style={styles.spValue} testID="earn-sp-value">
                  {spInfo.earn_sp} SP
                </Text>
              </View>
              <View style={styles.spRow}>
                <Text style={styles.spLabel}>💰 Buyer can use up to:</Text>
                <Text style={styles.spValue} testID="max-spend-sp-value">
                  {spInfo.max_spend_sp} SP ({spInfo.spend_percent}%)
                </Text>
              </View>
            </>
          ) : null}
        </View>
      )}

