/**
 * CategoryFilterChip - Filterable category chip for discovery flows.
 * 
 * TASK ADMIN-V3-007: Hide categories with item_count=0.
 * Server already filters these via getCategoriesWithCounts(false),
 * but this component enforces the rule client-side as well.
 * 
 * Renders bonus badge when sp_earning_multiplier > 1.10 (strict >).
 */
export function CategoryFilterChip({
  id,
  name,
  icon,
  item_count = 0,
  sp_earning_multiplier,
  bonus_badge_icon_url,
  isSelected,
  onPress,
  testID = `category-chip-${id}`,
}: CategoryFilterChipProps) {
  // TASK ADMIN-V3-007: Never render zero-count categories
  if (item_count === 0) {
    return null;
  }

  const showBonusBadge = Number(sp_earning_multiplier ?? 1.1) > 1.1;

  return (
    <TouchableOpacity
      style={[styles.chip, isSelected && styles.chipSelected]}
      onPress={() => onPress(id)}
      accessibilityLabel={`Filter by ${name} category`}
      accessibilityRole="button"
      accessibilityState={{ selected: isSelected }}
      testID={testID}
    >
      <View style={styles.chipContent}>
        {icon && <Text style={styles.icon}>{icon}</Text>}
        <Text style={[styles.name, isSelected && styles.nameSelected]}>
          {name}
        </Text>
        {item_count !== undefined && (
          <Text style={[styles.count, isSelected && styles.countSelected]}>
            ({item_count})
          </Text>
        )}
        {showBonusBadge && (
          <View style={styles.badgeContainer}>
            <BonusBadge 
              iconUrl={bonus_badge_icon_url} 
              size={16}
              testID={`${testID}-bonus-badge`}
            />
          </View>
        )}
      </View>
    </TouchableOpacity>
  );
}

