/**
 * File: p2p-kids-marketplace/src/__tests__/services/categoryService.calculateCategorySP.test.ts
 * TASK ADMIN-V3-007: Unit tests for calculateCategorySP function
 * 
 * Tests category-specific SP earning and spending calculations.
 */

import { calculateCategorySP } from '../../services/categoryService';
import { supabase } from '../../config/supabase';

// Mock Supabase
jest.mock('../../config/supabase', () => ({
  supabase: {
    from: jest.fn(),
  },
}));

describe('calculateCategorySP', () => {
  const mockFrom = supabase.from as jest.MockedFunction<typeof supabase.from>;

  beforeEach(() => {
    jest.clearAllMocks();
  });

  it('should calculate SP with custom category multiplier and cap', async () => {
    // Mock category with 1.20 multiplier and 70% cap
    mockFrom.mockReturnValue({
      select: jest.fn().mockReturnValue({
        eq: jest.fn().mockReturnValue({
          single: jest.fn().mockResolvedValue({
            data: {
              sp_earning_multiplier: 1.20,
              sp_spending_cap_percent: 70,
            },
            error: null,
          }),
        }),
      }),
    } as any);

    const result = await calculateCategorySP('cat-123', 50);

    expect(result).toEqual({
      earn_sp: 60, // Math.round(50 * 1.20) = 60
      max_spend_sp: 35, // Math.floor(50 * 0.70) = 35
      spend_percent: 70,
    });
  });

  it('should use default fallback when category not found', async () => {
    mockFrom.mockReturnValue({
      select: jest.fn().mockReturnValue({
        eq: jest.fn().mockReturnValue({
          single: jest.fn().mockResolvedValue({
            data: null,
            error: { message: 'Not found' },
          }),
        }),
      }),
    } as any);

    const result = await calculateCategorySP('invalid-id', 100);

    expect(result).toEqual({
      earn_sp: 110, // Math.round(100 * 1.10) = 110
      max_spend_sp: 50, // Math.floor(100 * 0.50) = 50
      spend_percent: 50,
    });
  });

  it('should handle null multiplier and cap with defaults', async () => {
    mockFrom.mockReturnValue({
      select: jest.fn().mockReturnValue({
        eq: jest.fn().mockReturnValue({
          single: jest.fn().mockResolvedValue({
            data: {
              sp_earning_multiplier: null,
              sp_spending_cap_percent: null,
            },
            error: null,
          }),
        }),
      }),
    } as any);

    const result = await calculateCategorySP('cat-456', 80);

    expect(result).toEqual({
      earn_sp: 88, // Math.round(80 * 1.10)
      max_spend_sp: 40, // Math.floor(80 * 0.50)
      spend_percent: 50,
    });
  });

  it('should round earn_sp correctly (Math.round)', async () => {
    mockFrom.mockReturnValue({
      select: jest.fn().mockReturnValue({
        eq: jest.fn().mockReturnValue({
          single: jest.fn().mockResolvedValue({
            data: {
              sp_earning_multiplier: 1.15,
              sp_spending_cap_percent: 60,
            },
            error: null,
          }),
        }),
      }),
    } as any);

    const result = await calculateCategorySP('cat-789', 33.33);

    // 33.33 * 1.15 = 38.3295 → Math.round = 38
    expect(result.earn_sp).toBe(38);
  });

  it('should floor max_spend_sp correctly (Math.floor)', async () => {
    mockFrom.mockReturnValue({
      select: jest.fn().mockReturnValue({
        eq: jest.fn().mockReturnValue({
          single: jest.fn().mockResolvedValue({
            data: {
              sp_earning_multiplier: 1.25,
              sp_spending_cap_percent: 75,
            },
            error: null,
          }),
        }),
      }),
    } as any);

    const result = await calculateCategorySP('cat-999', 33.99);

    // 33.99 * 0.75 = 25.4925 → Math.floor = 25
    expect(result.max_spend_sp).toBe(25);
  });

  it('should handle Supabase query errors gracefully', async () => {
    mockFrom.mockImplementation(() => {
      throw new Error('Network error');
    });

    const result = await calculateCategorySP('cat-error', 75);

    // Should fall back to defaults
    expect(result).toEqual({
      earn_sp: 83, // Math.round(75 * 1.10)
      max_spend_sp: 37, // Math.floor(75 * 0.50)
      spend_percent: 50,
    });
  });

  it('should handle maximum multiplier (1.40) and cap (80%)', async () => {
    mockFrom.mockReturnValue({
      select: jest.fn().mockReturnValue({
        eq: jest.fn().mockReturnValue({
          single: jest.fn().mockResolvedValue({
            data: {
              sp_earning_multiplier: 1.40,
              sp_spending_cap_percent: 80,
            },
            error: null,
          }),
        }),
      }),
    } as any);

    const result = await calculateCategorySP('cat-max', 100);

    expect(result).toEqual({
      earn_sp: 140, // Math.round(100 * 1.40)
      max_spend_sp: 80, // Math.floor(100 * 0.80)
      spend_percent: 80,
    });
  });

  it('should handle minimum multiplier (1.05) and cap (50%)', async () => {
    mockFrom.mockReturnValue({
      select: jest.fn().mockReturnValue({
        eq: jest.fn().mockReturnValue({
          single: jest.fn().mockResolvedValue({
            data: {
              sp_earning_multiplier: 1.05,
              sp_spending_cap_percent: 50,
            },
            error: null,
          }),
        }),
      }),
    } as any);

    const result = await calculateCategorySP('cat-min', 100);

    expect(result).toEqual({
      earn_sp: 105, // Math.round(100 * 1.05)
      max_spend_sp: 50, // Math.floor(100 * 0.50)
      spend_percent: 50,
    });
  });
});

