/**
 * File: p2p-kids-marketplace/e2e/admin-v3-007-category-sp-integration.test.ts
 * TASK ADMIN-V3-007: Integration tests for category SP calculations
 * 
 * Tests end-to-end category-specific SP earning and spending against staging Supabase.
 * 
 * Run with: RUN_SUPABASE_E2E=true npm run test:e2e
 */

import { supabase } from '../src/config/supabase';
import {
  calculateCategorySP,
  getCategoriesWithCounts,
  getBonusCategories,
} from '../src/services/categoryService';

const SKIP_E2E = !process.env.RUN_SUPABASE_E2E;

describe('ADMIN-V3-007 Category SP Integration', () => {
  beforeAll(() => {
    if (SKIP_E2E) {
      console.log('⏭️  Skipping E2E tests. Set RUN_SUPABASE_E2E=true to run against staging.');
    }
  });

  describe('getCategoriesWithCounts', () => {
    it('should return only active categories with item_count > 0 for buyer flows', async () => {
      if (SKIP_E2E) return;

      const categories = await getCategoriesWithCounts(false);

      // All returned categories should be active and have items
      categories.forEach((cat) => {
        expect(cat.is_active).toBe(true);
        expect(cat.item_count).toBeGreaterThan(0);
      });

      // Categories should be ordered by display_order
      for (let i = 1; i < categories.length; i++) {
        expect(categories[i].display_order).toBeGreaterThanOrEqual(
          categories[i - 1].display_order
        );
      }
    });

    it('should include icon_url and bonus_badge_icon_url fields', async () => {
      if (SKIP_E2E) return;

      const categories = await getCategoriesWithCounts(false);

      if (categories.length > 0) {
        const firstCat = categories[0];
        expect(firstCat).toHaveProperty('icon_url');
        expect(firstCat).toHaveProperty('bonus_badge_icon_url');
        expect(firstCat).toHaveProperty('sp_earning_multiplier');
      }
    });

    it('should include all categories when includeInactive=true', async () => {
      if (SKIP_E2E) return;

      const allCategories = await getCategoriesWithCounts(true);
      const activeCategories = await getCategoriesWithCounts(false);

      // All categories should be >= active categories
      expect(allCategories.length).toBeGreaterThanOrEqual(activeCategories.length);
    });
  });

  describe('getBonusCategories', () => {
    it('should return only active categories with sp_earning_multiplier > 1.10', async () => {
      if (SKIP_E2E) return;

      const bonusCategories = await getBonusCategories();

      bonusCategories.forEach((cat) => {
        expect(cat.is_active).toBe(true);
        expect(cat.sp_earning_multiplier).toBeGreaterThan(1.10);
      });
    });

    it('should order bonus categories by sp_earning_multiplier DESC', async () => {
      if (SKIP_E2E) return;

      const bonusCategories = await getBonusCategories();

      for (let i = 1; i < bonusCategories.length; i++) {
        expect(bonusCategories[i - 1].sp_earning_multiplier!).toBeGreaterThanOrEqual(
          bonusCategories[i].sp_earning_multiplier!
        );
      }
    });
  });

  describe('calculateCategorySP', () => {
    it('should calculate SP for a real category from staging DB', async () => {
      if (SKIP_E2E) return;

      // Get first active category
      const categories = await getCategoriesWithCounts(false);
      if (categories.length === 0) {
        console.warn('⚠️  No categories found in staging DB - skipping test');
        return;
      }

      const category = categories[0];
      const price = 50;

      const spInfo = await calculateCategorySP(category.id, price);

      // Verify structure
      expect(spInfo).toHaveProperty('earn_sp');
      expect(spInfo).toHaveProperty('max_spend_sp');
      expect(spInfo).toHaveProperty('spend_percent');

      // Verify earn_sp is rounded correctly
      expect(Number.isInteger(spInfo.earn_sp)).toBe(true);

      // Verify max_spend_sp is floored correctly
      expect(Number.isInteger(spInfo.max_spend_sp)).toBe(true);

      // Verify spend_percent is within valid range
      expect(spInfo.spend_percent).toBeGreaterThanOrEqual(50);
      expect(spInfo.spend_percent).toBeLessThanOrEqual(80);

      // Log for manual verification
      console.log(`✅ Category "${category.name}" SP calculation:`, {
        price,
        ...spInfo,
      });
    });

    it('should handle bonus category with elevated multiplier', async () => {
      if (SKIP_E2E) return;

      const bonusCategories = await getBonusCategories();
      if (bonusCategories.length === 0) {
        console.warn('⚠️  No bonus categories in staging DB - skipping test');
        return;
      }

      const bonusCategory = bonusCategories[0];
      const price = 100;

      const spInfo = await calculateCategorySP(bonusCategory.id, price);

      // For a bonus category with multiplier > 1.10, earn_sp should be > price * 1.10
      const baselineEarning = Math.round(price * 1.10);
      expect(spInfo.earn_sp).toBeGreaterThan(baselineEarning);

      console.log(`✅ Bonus category "${bonusCategory.name}" (${bonusCategory.sp_earning_multiplier}x):`, {
        price,
        ...spInfo,
      });
    });

    it('should calculate correctly for edge case prices', async () => {
      if (SKIP_E2E) return;

      const categories = await getCategoriesWithCounts(false);
      if (categories.length === 0) return;

      const category = categories[0];

      // Test fractional price
      const result1 = await calculateCategorySP(category.id, 33.33);
      expect(result1.earn_sp).toBeGreaterThan(0);
      expect(result1.max_spend_sp).toBeGreaterThan(0);

      // Test small price
      const result2 = await calculateCategorySP(category.id, 5);
      expect(result2.earn_sp).toBeGreaterThan(0);
      expect(result2.max_spend_sp).toBeGreaterThan(0);

      // Test large price
      const result3 = await calculateCategorySP(category.id, 500);
      expect(result3.earn_sp).toBeGreaterThan(0);
      expect(result3.max_spend_sp).toBeGreaterThan(0);
      expect(result3.max_spend_sp).toBeLessThanOrEqual(500 * 0.8); // Max 80%
    });
  });

  describe('Zero-count category filtering', () => {
    it('should never return categories with item_count=0 in buyer flow', async () => {
      if (SKIP_E2E) return;

      const categories = await getCategoriesWithCounts(false);

      const zeroCountCategories = categories.filter((cat) => cat.item_count === 0);
      expect(zeroCountCategories).toHaveLength(0);
    });
  });
});

