          style={[styles.image, { width: size, height: size }]}
          resizeMode="cover"
          testID={`${testID}-image`}
        />
      </View>
    );
  }

  return (
    <Text
      style={[styles.emoji, { fontSize: size }]}
      accessibilityLabel="Bonus category"
      testID={`${testID}-emoji`}
    >
      ⭐
    </Text>
  );
}

