      });

      // Categories should be ordered by display_order
      for (let i = 1; i < categories.length; i++) {
        expect(categories[i].display_order).toBeGreaterThanOrEqual(
          categories[i - 1].display_order
        );
      }
    });

    it('should include icon_url and bonus_badge_icon_url fields', async () => {
      if (SKIP_E2E) return;

      const categories = await getCategoriesWithCounts(false);

      if (categories.length > 0) {
        const firstCat = categories[0];
        expect(firstCat).toHaveProperty('icon_url');
        expect(firstCat).toHaveProperty('bonus_badge_icon_url');
        expect(firstCat).toHaveProperty('sp_earning_multiplier');
      }
    });

    it('should include all categories when includeInactive=true', async () => {
