      if (SKIP_E2E) return;

      const bonusCategories = await getBonusCategories();

      bonusCategories.forEach((cat) => {
        expect(cat.is_active).toBe(true);
        expect(cat.sp_earning_multiplier).toBeGreaterThan(1.10);
      });
    });

    it('should order bonus categories by sp_earning_multiplier DESC', async () => {
      if (SKIP_E2E) return;

      const bonusCategories = await getBonusCategories();

      for (let i = 1; i < bonusCategories.length; i++) {
        expect(bonusCategories[i - 1].sp_earning_multiplier!).toBeGreaterThanOrEqual(
          bonusCategories[i].sp_earning_multiplier!
