 */
export async function calculateCategorySP(
  categoryId: string,
  price: number
): Promise<{
  earn_sp: number;
  max_spend_sp: number;
  spend_percent: number;
} | null> {
  try {
    const { data: category, error } = await supabase
      .from('categories')
      .select('sp_earning_multiplier, sp_spending_cap_percent')
