/**
 * File: p2p-kids-marketplace/src/components/discovery/CategoryFilterChip.tsx
 * TASK ADMIN-V3-007: Category Filter Chip
 * Module: MODULE-12-ADMIN-V3-CATEGORIES
 * 
 * Renders a filter chip for categories in discovery/search flows.
 */

import React from 'react';
import { TouchableOpacity, Text, Image, StyleSheet } from 'react-native';
import { BonusBadge } from '../shared/BonusBadge';

export interface CategoryFilterChipProps {
  /** Category ID */
  id: string;
  /** Category name */
  name: string;
  /** Category emoji icon */
  icon?: string | null;
  /** Custom category icon URL */
  icon_url?: string | null;
  /** Bonus badge icon URL */
  bonus_badge_icon_url?: string | null;
  /** SP earning multiplier (> 1.10 shows bonus badge) */
  sp_earning_multiplier?: number;
  /** Item count (currently informational only) */
  item_count?: number;
  /** Whether this chip is selected */
  selected?: boolean;
  /** Callback when chip is pressed */
  onPress?: (id: string) => void;
  /** Test ID */
  testID?: string;
}

export function CategoryFilterChip({
  id,
  name,
  icon,
  icon_url,
  bonus_badge_icon_url,
  sp_earning_multiplier,
  item_count: _itemCount,
  selected = false,
  onPress,
  testID = `category-chip-${id}`,
}: CategoryFilterChipProps) {
  const showBonusBadge = Number(sp_earning_multiplier ?? 1.1) > 1.1;

  const handlePress = () => {
    if (onPress) {
      onPress(id);
    }
  };

  return (
    <TouchableOpacity
      style={[styles.chip, selected && styles.chipSelected]}
      onPress={handlePress}
      activeOpacity={0.7}
      accessibilityLabel={`Filter by category: ${name}`}
      accessibilityRole="button"
      accessibilityState={{ selected }}
      testID={testID}
    >
      {/* Icon */}
      {icon_url ? (
        <Image
          source={{ uri: icon_url }}
          style={styles.iconImage}
          resizeMode="cover"
        />
      ) : icon && icon.trim().length > 0 ? (
        <Text style={styles.iconText}>{icon}</Text>
      ) : (
        <Text style={styles.iconText}>📦</Text>
      )}

      {/* Name */}
      <Text style={[styles.name, selected && styles.nameSelected]}>{name}</Text>

      {/* Bonus Badge */}
      {showBonusBadge && (
        <BonusBadge
          iconUrl={bonus_badge_icon_url}
          size="small"
          style={styles.bonusBadge}
          testID={`${testID}-bonus`}
        />
      )}
    </TouchableOpacity>
  );
}

const styles = StyleSheet.create({
  chip: {
    flexDirection: 'row',
    alignItems: 'center',
    paddingHorizontal: 14,
    paddingVertical: 8,
    backgroundColor: '#F5F5F5',
    borderRadius: 20,
    marginRight: 8,
    marginBottom: 8,
    borderWidth: 1,
    borderColor: '#E0E0E0',
  },
  chipSelected: {
    backgroundColor: '#E3F2FD',
    borderColor: '#007AFF',
  },
  iconImage: {
    width: 18,
    height: 18,
    borderRadius: 4,
    marginRight: 6,
  },
  iconText: {
    fontSize: 16,
    marginRight: 6,
  },
  name: {
    fontSize: 14,
    color: '#333333',
    fontWeight: '500',
  },
  nameSelected: {
    color: '#007AFF',
    fontWeight: '600',
  },
  bonusBadge: {
    marginLeft: 4,
  },
});

/**
 * File: p2p-kids-marketplace/src/__tests__/services/categoryService-admin-v3-007.test.ts
 * TASK ADMIN-V3-007: Unit tests for category service V3 enhancements
 * Module: MODULE-12-ADMIN-V3-CATEGORIES
 * 
 * Tests:
 * - getBonusCategories filtering (sp_earning_multiplier > 1.10)
 * - calculateCategorySP rounding rules
 * - getCategoriesWithCounts filters inactive only (zero-count still visible)
 */

import { supabase } from '../../config/supabase';
import * as categoryService from '../../services/categoryService';

// Mock Supabase
jest.mock('../../config/supabase', () => ({
  supabase: {
    from: jest.fn(),
  },
}));

describe('Category Service (MODULE-12 V3)', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  describe('getBonusCategories', () => {
    it('returns only categories with sp_earning_multiplier > 1.10', async () => {
      const mockData = [
        {
          id: 'cat1',
          name: 'Electronics',
          sp_earning_multiplier: 1.25,
          is_active: true,
        },
        {
          id: 'cat2',
          name: 'Toys',
          sp_earning_multiplier: 1.40,
          is_active: true,
        },
      ];

      (supabase.from as jest.Mock).mockReturnValue({
        select: jest.fn().mockReturnThis(),
        eq: jest.fn().mockReturnThis(),
        gt: jest.fn().mockReturnThis(),
        order: jest.fn().mockResolvedValue({ data: mockData, error: null }),
      });

      const result = await categoryService.getBonusCategories();

      expect(supabase.from).toHaveBeenCalledWith('categories');
      expect(result).toHaveLength(2);
      expect(result[0].sp_earning_multiplier).toBeGreaterThan(1.10);
    });

    it('returns empty array when no bonus categories exist', async () => {
      (supabase.from as jest.Mock).mockReturnValue({
        select: jest.fn().mockReturnThis(),
        eq: jest.fn().mockReturnThis(),
        gt: jest.fn().mockReturnThis(),
        order: jest.fn().mockResolvedValue({ data: [], error: null }),
      });

      const result = await categoryService.getBonusCategories();

      expect(result).toEqual([]);
    });

    it('handles database error gracefully', async () => {
      (supabase.from as jest.Mock).mockReturnValue({
        select: jest.fn().mockReturnThis(),
        eq: jest.fn().mockReturnThis(),
        gt: jest.fn().mockReturnThis(),
        order: jest.fn().mockResolvedValue({
          data: null,
          error: new Error('Database error'),
        }),
      });

      const result = await categoryService.getBonusCategories();

      expect(result).toEqual([]);
    });
  });

  describe('calculateCategorySP', () => {
    it('calculates SP earning with Math.round', async () => {
      const mockCategory = {
        sp_earning_multiplier: 1.15,
        sp_spending_cap_percent: 70,
      };

      (supabase.from as jest.Mock).mockReturnValue({
        select: jest.fn().mockReturnThis(),
        eq: jest.fn().mockReturnThis(),
        single: jest.fn().mockResolvedValue({ data: mockCategory, error: null }),
      });

      const result = await categoryService.calculateCategorySP('cat1', 49.99);

      // earn_sp = Math.round(49.99 * 1.15) = Math.round(57.4885) = 57
      expect(result?.earn_sp).toBe(57);
    });

    it('calculates max_spend_sp with Math.floor', async () => {
      const mockCategory = {
        sp_earning_multiplier: 1.10,
        sp_spending_cap_percent: 70,
      };

      (supabase.from as jest.Mock).mockReturnValue({
        select: jest.fn().mockReturnThis(),
        eq: jest.fn().mockReturnThis(),
        single: jest.fn().mockResolvedValue({ data: mockCategory, error: null }),
      });

      const result = await categoryService.calculateCategorySP('cat1', 50);

      // max_spend_sp = Math.floor((50 * 70) / 100) = Math.floor(35) = 35
      expect(result?.max_spend_sp).toBe(35);
    });

    it('uses default multiplier 1.10 when null', async () => {
      const mockCategory = {
        sp_earning_multiplier: null,
        sp_spending_cap_percent: 70,
      };

      (supabase.from as jest.Mock).mockReturnValue({
        select: jest.fn().mockReturnThis(),
        eq: jest.fn().mockReturnThis(),
        single: jest.fn().mockResolvedValue({ data: mockCategory, error: null }),
      });

      const result = await categoryService.calculateCategorySP('cat1', 100);

      // earn_sp = Math.round(100 * 1.10) = 110
      expect(result?.earn_sp).toBe(110);
    });

    it('returns null when category not found', async () => {
      (supabase.from as jest.Mock).mockReturnValue({
        select: jest.fn().mockReturnThis(),
        eq: jest.fn().mockReturnThis(),
        single: jest.fn().mockResolvedValue({ data: null, error: null }),
      });

      const result = await categoryService.calculateCategorySP('invalid-cat', 100);

      expect(result).toBeNull();
    });

    it('returns null on database error', async () => {
      (supabase.from as jest.Mock).mockReturnValue({
        select: jest.fn().mockReturnThis(),
        eq: jest.fn().mockReturnThis(),
        single: jest.fn().mockResolvedValue({
          data: null,
          error: new Error('DB error'),
        }),
      });

      const result = await categoryService.calculateCategorySP('cat1', 100);

      expect(result).toBeNull();
    });
  });

  describe('getCategoriesWithCounts', () => {
    it('filters out inactive categories by default', async () => {
      const mockData = [
        { id: 'cat1', name: 'Active', is_active: true, item_count: 5 },
        { id: 'cat2', name: 'ZeroCountButActive', is_active: true, item_count: 0 },
      ];

      const mockQuery: any = {
        select: jest.fn().mockReturnThis(),
        eq: jest.fn().mockReturnThis(),
        order: jest.fn().mockReturnThis(),
        then: (resolve: (value: { data: typeof mockData; error: null }) => unknown) =>
          resolve({ data: mockData, error: null }),
      };

      (supabase.from as jest.Mock).mockReturnValue(mockQuery);

      const result = await categoryService.getCategoriesWithCounts(false);

      expect(mockQuery.eq).toHaveBeenCalledWith('is_active', true);
      expect(result).toEqual(mockData);
    });

    it('does not filter out zero-count categories by default', async () => {
      const mockData = [
        { id: 'cat1', name: 'HasItems', is_active: true, item_count: 3 },
        { id: 'cat2', name: 'ZeroItems', is_active: true, item_count: 0 },
      ];

      const mockQuery: any = {
        select: jest.fn().mockReturnThis(),
        eq: jest.fn().mockReturnThis(),
        order: jest.fn().mockReturnThis(),
        then: (resolve: (value: { data: typeof mockData; error: null }) => unknown) =>
          resolve({ data: mockData, error: null }),
      };

      (supabase.from as jest.Mock).mockReturnValue(mockQuery);

      const result = await categoryService.getCategoriesWithCounts(false);

      // Verify active filter is still applied
      expect(mockQuery.eq).toHaveBeenCalledWith('is_active', true);
      expect(result).toEqual(mockData);
    });

    it('includes all categories when includeInactive=true', async () => {
      const mockData = [
        { id: 'cat1', name: 'Active', is_active: true, item_count: 5 },
        { id: 'cat2', name: 'Inactive', is_active: false, item_count: 0 },
      ];

      const mockQuery: any = {
        select: jest.fn().mockReturnThis(),
        order: jest.fn().mockReturnThis(),
        then: (resolve: (value: { data: typeof mockData; error: null }) => unknown) =>
          resolve({ data: mockData, error: null }),
      };

      (supabase.from as jest.Mock).mockReturnValue(mockQuery);

      const result = await categoryService.getCategoriesWithCounts(true);

      // Should not call eq when includeInactive=true
      expect(mockQuery).not.toHaveProperty('eq');
      expect(result).toEqual(mockData);
    });
  });
});

/**
 * File: p2p-kids-marketplace/src/components/shared/BonusBadge.tsx
 * TASK ADMIN-V3-007: Bonus Badge Component
 * Module: MODULE-12-ADMIN-V3-CATEGORIES
 * 
 * Renders a bonus badge (custom icon or ⭐ emoji fallback)
 * for categories with sp_earning_multiplier > 1.10
 */

import React, { useEffect, useState } from 'react';
import { View, Text, Image, StyleSheet, ViewStyle } from 'react-native';

export interface BonusBadgeProps {
  /** Custom bonus badge icon URL from Supabase Storage */
  iconUrl?: string | null;
  /** Size of the badge (small, medium, large) */
  size?: 'small' | 'medium' | 'large';
  /** Custom style override */
  style?: ViewStyle;
  /** Test ID for testing */
  testID?: string;
}

export function BonusBadge({
  iconUrl,
  size = 'small',
  style,
  testID = 'bonus-badge',
}: BonusBadgeProps) {
  const [imageLoadFailed, setImageLoadFailed] = useState(false);

  useEffect(() => {
    // Reset image fallback state when the icon URL changes.
    setImageLoadFailed(false);
  }, [iconUrl]);

  const sizeStyles = {
    small: styles.small,
    medium: styles.medium,
    large: styles.large,
  };

  const imageSizeStyles = {
    small: styles.imageSmall,
    medium: styles.imageMedium,
    large: styles.imageLarge,
  };

  const textSizeStyles = {
    small: styles.textSmall,
    medium: styles.textMedium,
    large: styles.textLarge,
  };

  // If custom icon URL is provided, use Image component with expo-image
  if (iconUrl && iconUrl.trim().length > 0 && !imageLoadFailed) {
    return (
      <View style={[sizeStyles[size], style]} testID={testID}>
        <Image
          source={{ uri: iconUrl }}
          style={imageSizeStyles[size]}
          resizeMode="cover"
          onError={() => setImageLoadFailed(true)}
          accessibilityLabel="Bonus category badge"
        />
      </View>
    );
  }

  // Fallback to ⭐ emoji
  return (
    <View style={[sizeStyles[size], style]} testID={`${testID}-fallback`}>
      <Text style={textSizeStyles[size]} accessibilityLabel="Bonus category badge">
        ⭐
      </Text>
    </View>
  );
}

const styles = StyleSheet.create({
  // Container sizes
  small: {
    width: 16,
    height: 16,
    justifyContent: 'center',
    alignItems: 'center',
  },
  medium: {
    width: 24,
    height: 24,
    justifyContent: 'center',
    alignItems: 'center',
  },
  large: {
    width: 32,
    height: 32,
    justifyContent: 'center',
    alignItems: 'center',
  },

  // Image sizes
  imageSmall: {
    width: 16,
    height: 16,
  },
  imageMedium: {
    width: 24,
    height: 24,
  },
  imageLarge: {
    width: 32,
    height: 32,
  },

  // Text (emoji) sizes
  textSmall: {
    fontSize: 14,
    lineHeight: 16,
  },
  textMedium: {
    fontSize: 20,
    lineHeight: 24,
  },
  textLarge: {
    fontSize: 28,
    lineHeight: 32,
  },
});

/**
 * File: p2p-kids-marketplace/src/__tests__/components/shared/BonusBadge.test.tsx
